// PROTOTYPE build step: inlines chess.js's ESM browser build into a JS module
// the Worker can import and re-serve verbatim as a static asset.
// Run with: node scripts/build-vendor.mjs
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("node_modules/chess.js/dist/esm/chess.js", "utf8");
// drop the sourcemap comment — we don't ship the .map file
const cleaned = src.replace(/\/\/# sourceMappingURL=.*$/m, "");

writeFileSync(
  "src/vendor-chess-source.js",
  `// GENERATED by scripts/build-vendor.mjs from chess.js — do not edit by hand.\nexport default ${JSON.stringify(cleaned)};\n`
);
console.log("Wrote src/vendor-chess-source.js");
